// Website form or Facebook Lead Ads payload -> one flat lead. t0 = when n8n received it.
const t0 = Date.now();
const raw = $input.first().json.body;
const body = raw && typeof raw === 'object' ? raw : {};
const clean = (v, max = 500) => String(v ?? '').replace(/\s+/g, ' ').trim().slice(0, max);
let lead;
if (body.source === 'facebook' || 'field_data' in body) {
  const fields = Array.isArray(body.field_data) ? body.field_data : [];
  const f = Object.fromEntries(fields.filter(d => d && d.name).map(d => [d.name, (d.values || [])[0] ?? '']));
  lead = { source: 'facebook', submission_id: body.leadgen_id, name: f.full_name, email: f.email,
           phone: f.phone_number, city: f.city, service: f.what_service_do_you_need,
           message: f.tell_us_about_your_project };
} else {
  lead = { source: body.source === 'website' ? 'website' : 'unknown', submission_id: body.submission_id,
           name: body.name, email: body.email, phone: body.phone, city: body.city, service: body.service,
           message: body.message };
}
for (const k of Object.keys(lead)) lead[k] = clean(lead[k], k === 'message' ? 2000 : 200);
lead.email = lead.email.toLowerCase();
lead.email_valid = /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(lead.email);
lead.city = lead.city.toLowerCase().replace(/(^|[\s-])\p{L}/gu, c => c.toUpperCase());
const [first, ...rest] = lead.name.split(' ');
lead.firstname = first || '';
lead.lastname = rest.join(' ');
lead.submission_id = lead.submission_id || `n8n-${$execution.id}`;
lead.execution_id = String($execution.id);
lead.t0_ms = t0;
lead.t0 = new Date(t0).toISOString();
// Office hours from business.md: Monday to Saturday, 7:00 am to 6:00 pm Eastern.
const parts = Object.fromEntries(new Intl.DateTimeFormat('en-US', {
  timeZone: 'America/New_York', weekday: 'short', hour: 'numeric', hourCycle: 'h23' })
  .formatToParts(new Date(t0)).map(p => [p.type, p.value]));
lead.office_open = parts.weekday !== 'Sun' && Number(parts.hour) >= 7 && Number(parts.hour) < 18;
lead.now_eastern = new Date(t0).toLocaleString('en-US', {
  timeZone: 'America/New_York', weekday: 'long', year: 'numeric', month: 'long', day: 'numeric',
  hour: 'numeric', minute: '2-digit' });
return [{ json: lead }];

// Claim a Lead log row the moment the lead arrives (appended with Google's append API, so concurrent
// leads never collide). Dedupe reads these claims; the final outcome later updates this same row.
const s = $json;
return [{ json: { execution_id: s.execution_id, submission_id: s.submission_id, source: s.source, name: s.name,
                  email: s.email, t0: s.t0, status: 'processing' } }];

// Dedupe against Lead log rows for the same email, in claim order (row number):
//  - an earlier row with the same submission_id -> duplicate delivery: drop it
//  - an earlier lead in the last 24 h that was handled (replied or in the CRM) or is still processing
//    -> repeat: note only, no second reply. Spam and leads that got nowhere don't count.
const lead = $('Normalize lead').first().json;
const DAY_MS = 24 * 3600 * 1000;
const PROCESSING_MAX_MS = 10 * 60 * 1000;  // a run takes seconds; an older "processing" row is a crashed run
const CLOCK_SLACK_MS = 60 * 1000;
const items = $input.all().map(i => i.json);
const problems = [];
const readError = items.find(r => r && r.error);
if (readError) problems.push(`Dedupe check failed: ${String(readError.error.message || readError.error).slice(0, 200)}`);
try {
  const claim = $('Claim lead').first().json;
  if (claim.error) problems.push(`Could not claim a Lead log row: ${String(claim.error.message || claim.error).slice(0, 200)}`);
} catch (e) { /* claim node always runs before this one */ }
const rows = items.filter(r => r && !r.error && r.email !== undefined);
const own = rows.find(r => String(r.execution_id) === lead.execution_id);
const ownRow = own ? Number(own.row_number) : Infinity;
const earlier = !lead.email_valid ? [] : rows.filter(r =>
  String(r.execution_id) !== lead.execution_id && Number(r.row_number) < ownRow &&
  String(r.email).toLowerCase() === lead.email);
const duplicate = earlier.some(r => String(r.submission_id) === lead.submission_id);
const handled = r => {
  // Claim order (row number) decides who is first; a row claimed earlier can still carry a t0 a little later
  // than ours when two leads arrive together, so a small negative age still counts.
  const age = lead.t0_ms - Date.parse(r.t0);
  if (!(age > -CLOCK_SLACK_MS && age < DAY_MS)) return false;
  if (r.status === 'processing') return age < PROCESSING_MAX_MS;
  return r.tier !== 'spam' && (r.replied === 'yes' || String(r.crm_id || '') !== '');
};
const prior = earlier.filter(handled);
return [{ json: { ...lead, duplicate, repeat: !duplicate && prior.length > 0, problems } }];

// Parse the model's JSON and pick the route: crm (new lead), repeat_note, or finish (spam / AI failed).
const lead = $('Build AI request').first().json;
const res = $input.first().json;
const BOOKING_LINK = '__ENV_BOOKING_LINK__';
const problems = [...lead.problems];
let ai = null;
if (res.error) {
  problems.push(`AI step failed: ${String(res.error.message || JSON.stringify(res.error)).slice(0, 200)}`);
} else {
  try {
    ai = JSON.parse(res.choices[0].message.content);
    if (!['hot', 'warm', 'cold', 'spam'].includes(ai.tier)) throw new Error(`unknown tier "${ai.tier}"`);
  } catch (e) {
    problems.push(`AI output unreadable: ${e.message}`);
    ai = null;
  }
}
// Hold any reply carrying a link other than the booking link (the lead's own text must never become a link we send).
if (ai && ai.reply_text) {
  const links = (ai.reply_text.match(/(https?:\/\/|www\.)[^\s)>\]]+/gi) || []).filter(u => !u.startsWith(BOOKING_LINK));
  if (links.length) {
    problems.push(`Reply held: it contains a link that is not the booking link (${links.join(' ').slice(0, 120)})`);
    ai = { ...ai, reply_text: null };
  }
}
let route = 'finish';
if (ai && lead.repeat) route = 'repeat_note';
else if (ai && ai.tier !== 'spam') route = 'crm';
const { ai_request, ...rest } = lead;
return [{ json: { ...rest, ai, tier: ai ? ai.tier : '', reason: ai ? ai.reason : '', route, problems } }];

// HubSpot request bodies. Contacts are upserted by email; a lead without a valid email gets a new contact.
const s = $json;
const esc = v => String(v ?? '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const props = { firstname: s.firstname, lastname: s.lastname, phone: s.phone, city: s.city,
                hs_lead_status: s.tier.toUpperCase() };
const contact = s.email_valid
  ? { url: 'https://api.hubapi.com/crm/v3/objects/contacts/batch/upsert',
      body: { inputs: [{ idProperty: 'email', id: s.email, properties: { ...props, email: s.email } }] } }
  : { url: 'https://api.hubapi.com/crm/v3/objects/contacts', body: { properties: props } };
const lines = [
  `<b>AI lead tier: ${esc(s.tier.toUpperCase())}</b>`,
  `Reason: ${esc(s.ai.reason)}`,
  `Service: ${esc(s.ai.service)} | Timeline: ${esc(s.ai.timeline)} | Language: ${esc(s.ai.language)}`,
  `Source: ${esc(s.source)} (${esc(s.submission_id)})`,
  `Message: "${esc(s.message)}"`,
];
if (!s.email_valid) lines.push(`Email given: "${esc(s.email)}" (invalid, no reply sent)`);
const note = { properties: { hs_timestamp: String(s.t0_ms), hs_note_body: lines.join('<br>') } };
const deal = { properties: { dealname: `${s.name} - ${s.ai.service}`.slice(0, 120),
                             pipeline: '__ENV_HUBSPOT_PIPELINE_ID__', dealstage: '__ENV_HUBSPOT_NEW_LEAD_STAGE_ID__' } };
const repeatNote = { properties: { hs_timestamp: String(s.t0_ms), hs_note_body: [
  `<b>Repeat enquiry within 24 h (no second reply sent)</b>`,
  `AI tier: ${esc(s.tier.toUpperCase())}. ${esc(s.reason)}`,
  `Source: ${esc(s.source)} (${esc(s.submission_id)})`,
  `Message: "${esc(s.message)}"`].join('<br>') } };
// Repeat enquiry: find the contact by email (upsert with only the email changes nothing on an existing
// contact, and still works if the first enquiry's run has not created it yet).
const findContact = { inputs: [{ idProperty: 'email', id: s.email, properties: { email: s.email } }] };
return [{ json: { ...s, hubspot: { contact, note, deal, repeatNote, findContact } } }];

// HubSpot request bodies. Contacts are upserted by email; a lead without a valid email gets a new contact.
const s = $json;
const esc = v => String(v ?? '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const props = { firstname: s.firstname, lastname: s.lastname, phone: s.phone, city: s.city,
                hs_lead_status: s.tier.toUpperCase() };
const contact = s.email_valid
  ? { url: 'https://api.hubapi.com/crm/v3/objects/contacts/batch/upsert',
      body: { inputs: [{ idProperty: 'email', id: s.email, properties: { ...props, email: s.email } }] } }
  : { url: 'https://api.hubapi.com/crm/v3/objects/contacts', body: { properties: props } };
const lines = [
  `<b>AI lead tier: ${esc(s.tier.toUpperCase())}</b>`,
  `Reason: ${esc(s.ai.reason)}`,
  `Service: ${esc(s.ai.service)} | Timeline: ${esc(s.ai.timeline)} | Language: ${esc(s.ai.language)}`,
  `Source: ${esc(s.source)} (${esc(s.submission_id)})`,
  `Message: "${esc(s.message)}"`,
];
if (!s.email_valid) lines.push(`Email given: "${esc(s.email)}" (invalid, no reply sent)`);
const note = { properties: { hs_timestamp: String(s.t0_ms), hs_note_body: lines.join('<br>') } };
const deal = { properties: { dealname: `${s.name} - ${s.ai.service}`.slice(0, 120),
                             pipeline: '__ENV_HUBSPOT_PIPELINE_ID__', dealstage: '__ENV_HUBSPOT_NEW_LEAD_STAGE_ID__' } };
const repeatNote = { properties: { hs_timestamp: String(s.t0_ms), hs_note_body: [
  `<b>Repeat enquiry within 24 h (no second reply sent)</b>`,
  `AI tier: ${esc(s.tier.toUpperCase())}. ${esc(s.reason)}`,
  `Source: ${esc(s.source)} (${esc(s.submission_id)})`,
  `Message: "${esc(s.message)}"`].join('<br>') } };
// Repeat enquiry: find the contact by email (upsert with only the email changes nothing on an existing
// contact, and still works if the first enquiry's run has not created it yet).
const findContact = { inputs: [{ idProperty: 'email', id: s.email, properties: { email: s.email } }] };
return [{ json: { ...s, hubspot: { contact, note, deal, repeatNote, findContact } } }];

// The CRM box's only output: crm_id, crm_url and crm_problems. Swapping HubSpot for GoHighLevel, Zoho or
// Pipedrive means replacing the nodes in this box and keeping a node named "CRM result" with these fields.
const s = $('Read AI result').first().json;
const out = name => { try { return $(name).isExecuted ? $(name).first().json : null; } catch (e) { return null; } };
const errOf = j => j && j.error ? String(j.error.message || j.error.description || JSON.stringify(j.error)).slice(0, 200) : '';
const idOf = j => j ? String((j.results && j.results[0] && j.results[0].id) || j.id || '') : '';
const problems = [];
const contactNode = s.route === 'repeat_note' ? 'HubSpot: find contact' : 'HubSpot: upsert contact';
const contact = out(contactNode);
let crmId = '';
if (!contact) problems.push('HubSpot contact step did not run');
else if (errOf(contact)) problems.push(`HubSpot contact failed: ${errOf(contact)}`);
else if (!(crmId = idOf(contact))) problems.push('HubSpot returned no contact id');
for (const n of ['HubSpot: add note', 'HubSpot: create deal', 'HubSpot: note on existing contact']) {
  const j = out(n);
  if (j && errOf(j)) problems.push(`${n} failed: ${errOf(j)}`);
}
const crmUrl = crmId ? `https://__ENV_HUBSPOT_APP_HOST__/contacts/__ENV_HUBSPOT_PORTAL_ID__/record/0-1/${crmId}` : '';
return [{ json: { ...s, crm_id: crmId, crm_url: crmUrl, crm_problems: problems } }];

// Collect what happened on whichever path ran; any problem -> status failed (+ Slack "lead failed").
const read = name => { try { return $(name).isExecuted ? $(name).first().json : null; } catch (e) { return null; } };
const errOf = j => j && j.error ? String(j.error.message || j.error.description || JSON.stringify(j.error)).slice(0, 200) : '';
const crm = read('CRM result');
const s = crm || read('Read AI result') ||
  { ...$('Check repeat').first().json, ai: null, tier: '', reason: '', route: 'duplicate' };
const problems = [...(s.problems || []), ...(crm ? crm.crm_problems : [])];

let replied = 'no', t1 = null;
const mail = read('Send reply');
if (mail) {
  if (errOf(mail)) problems.push(`Reply email failed: ${errOf(mail)}`);
  else { replied = 'yes'; t1 = Date.now(); }
} else if (s.route === 'crm' && s.email_valid && !(s.ai && (s.ai.reply_text || '').trim()) &&
           !problems.some(p => p.startsWith('Reply held'))) {
  problems.push('AI returned no reply text');
}
let status = 'ok';
if (s.duplicate) status = 'duplicate';
else if (problems.length) status = 'failed';
else if (s.repeat) status = 'repeat';
return [{ json: { ...s, crm_id: crm ? crm.crm_id : '', crm_url: crm ? crm.crm_url : '', replied, t1_ms: t1,
                  problems, status } }];

// At most one Slack message per lead (hot lead, invalid contact, lead failed), so n8n's retry covers it whole.
const s = $('Finish').first().json;
// Slack mrkdwn: escape lead and AI text so it can't ping @channel or plant links.
const esc = v => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const link = s.crm_url ? `<${s.crm_url}|Open in HubSpot>` : 'not created (CRM step failed)';
const msg = esc(s.message.length > 300 ? s.message.slice(0, 300) + '…' : s.message);
const kinds = [], parts = [];
if (s.tier === 'hot' && !s.repeat && !s.duplicate) {
  kinds.push('hot');
  parts.push(`:fire: *Hot lead* - call within 1 business hour\n*Name:* ${esc(s.name)}\n*City:* ${esc(s.city)}\n` +
    `*Problem:* ${msg}\n*Why hot:* ${esc(s.reason)}\n*Phone:* ${esc(s.phone) || 'not given'}\n*CRM:* ${link}`);
}
if (!s.email_valid && s.tier && s.tier !== 'spam' && !s.repeat && !s.duplicate) {
  kinds.push('invalid_contact');
  parts.push(`:warning: *Invalid contact* - no reply could be sent\n*Name:* ${esc(s.name)} (${esc(s.city)})\n` +
    `*Email given:* \`${esc(s.email) || '(empty)'}\`\n*Phone:* ${esc(s.phone) || 'not given'}\n` +
    `*Tier:* ${esc(s.tier)} - ${esc(s.reason)}\n*CRM:* ${link}`);
}
if (s.status === 'failed') {
  kinds.push('lead_failed');
  parts.push(`:rotating_light: *Lead failed* - needs a person\n*Lead:* ${esc(s.name) || '(no name)'} ` +
    `(${esc(s.source)}, ${esc(s.submission_id)})\n*Reply sent:* ${s.replied}\n*Problems:* ${esc(s.problems.join('; '))}\n` +
    `Full row in the Lead log sheet.`);
}
return kinds.length ? [{ json: { kinds, text: parts.join('\n\n'), submission_id: s.submission_id } }] : [];

// One "Slack log" row per alert kind in the (single) Slack message.
const alert = $('Slack alerts').first().json;
const r = $input.first().json;
const code = r.statusCode || (r.error && (r.error.httpCode || r.error.status)) || '';
const ok = !r.error && Number(code || 200) < 300;
const ts = new Date().toISOString();
return alert.kinds.map(kind => ({ json: { ts, submission_id: alert.submission_id, kind, ok: String(ok),
                                          http_status: String(code || (r.error ? 'error' : 200)) } }));

// Final outcome for this lead's claimed Lead log row (matched on execution_id).
// A failed Slack post also marks the lead failed (the Slack log has the details).
const s = $('Finish').first().json;
const problems = [...s.problems];
let slackFailed = false;
try {
  if ($('Post to Slack').isExecuted) slackFailed = !!$('Post to Slack').first().json.error;
} catch (e) { /* no alert for this lead */ }
if (slackFailed) problems.push('Slack alert failed');
const status = slackFailed && s.status !== 'duplicate' ? 'failed' : s.status;
return [{ json: {
  execution_id: s.execution_id, submission_id: s.submission_id, source: s.source, name: s.name, email: s.email,
  t0: s.t0, t1: s.t1_ms ? new Date(s.t1_ms).toISOString() : '',
  seconds_to_reply: s.t1_ms ? ((s.t1_ms - s.t0_ms) / 1000).toFixed(2) : '',
  tier: s.tier, reason: s.reason, replied: s.replied, crm_id: s.crm_id, status, problems: problems.join('; '),
} }];
